/**
 * Path resolution utilities for handling import aliases and module resolution
 */

import * as path from 'path'

export interface PathAliases {
  [alias: string]: string
}

export class PathResolver {
  private aliases: PathAliases = {}
  private extensions = ['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.vue', '.svelte']

  constructor(
    private projectRoot: string,
    aliases?: PathAliases
  ) {
    if (aliases) {
      this.aliases = aliases
    }
  }

  /**
   * Set path aliases from tsconfig/jsconfig
   */
  setAliases(aliases: PathAliases): void {
    this.aliases = aliases
  }

  /**
   * Parse tsconfig paths and convert to path aliases
   */
  static parseTsConfigPaths(
    tsConfigPaths: Record<string, string[]> | undefined,
    baseUrl: string = '.'
  ): PathAliases {
    if (!tsConfigPaths) return {}

    const aliases: PathAliases = {}

    for (const [alias, paths] of Object.entries(tsConfigPaths)) {
      // Remove /* from alias (e.g., "@/*" -> "@")
      const cleanAlias = alias.replace(/\/\*$/, '')

      // Take first path and remove /* (e.g., "src/*" -> "src")
      const targetPath = paths[0]?.replace(/\/\*$/, '') || ''

      // Combine with baseUrl
      aliases[cleanAlias] = path.join(baseUrl, targetPath)
    }

    return aliases
  }

  /**
   * Resolve import path to absolute file path
   */
  resolve(importPath: string, fromFile: string): string | null {
    // Handle relative imports
    if (importPath.startsWith('.')) {
      const dir = path.dirname(fromFile)
      const resolved = path.resolve(this.projectRoot, dir, importPath)
      return this.tryResolveWithExtensions(resolved)
    }

    // Handle alias imports
    for (const [alias, aliasPath] of Object.entries(this.aliases)) {
      if (importPath.startsWith(alias)) {
        const rest = importPath.slice(alias.length)
        const resolved = path.resolve(
          this.projectRoot,
          aliasPath,
          rest.startsWith('/') ? rest.slice(1) : rest
        )
        return this.tryResolveWithExtensions(resolved)
      }
    }

    // Handle absolute imports from project root
    if (!importPath.startsWith('.') && !importPath.includes('/node_modules/')) {
      const resolved = path.resolve(this.projectRoot, importPath)
      const result = this.tryResolveWithExtensions(resolved)
      if (result) return result
    }

    // External package or unresolvable
    return null
  }

  /**
   * Try to resolve file with different extensions
   */
  private tryResolveWithExtensions(basePath: string): string | null {
    const fs = require('fs')

    // Try exact path first
    if (fs.existsSync(basePath) && fs.statSync(basePath).isFile()) {
      return basePath
    }

    // Try with extensions
    for (const ext of this.extensions) {
      const withExt = basePath + ext
      if (fs.existsSync(withExt) && fs.statSync(withExt).isFile()) {
        return withExt
      }
    }

    // Try index files
    for (const ext of this.extensions) {
      const indexPath = path.join(basePath, `index${ext}`)
      if (fs.existsSync(indexPath) && fs.statSync(indexPath).isFile()) {
        return indexPath
      }
    }

    return null
  }

  /**
   * Check if import is external (npm package)
   */
  isExternalImport(importPath: string): boolean {
    return (
      !importPath.startsWith('.') &&
      !importPath.startsWith('/') &&
      !Object.keys(this.aliases).some(alias => importPath.startsWith(alias))
    )
  }

  /**
   * Get relative path between two files
   */
  getRelativePath(from: string, to: string): string {
    return path.relative(path.dirname(from), to)
  }

  /**
   * Normalize path separators to forward slashes
   */
  static normalizePath(filePath: string): string {
    return filePath.split(path.sep).join('/')
  }
}
