/**
 * Claude AI provider for pattern detection
 */

import Anthropic from '@anthropic-ai/sdk'
import type { LLMConfig, LLMPatternDetectionResponse } from '../types'
import { PromptTemplates } from './PromptTemplates'

export class ClaudeProvider {
  private client: Anthropic
  private model: string
  private maxTokens: number
  private temperature: number

  constructor(config: LLMConfig) {
    this.client = new Anthropic({
      apiKey: config.apiKey,
    })

    this.model = config.model || 'claude-sonnet-4-5-20250929' // Sonnet 4.5
    this.maxTokens = config.maxTokens || 4096
    this.temperature = config.temperature || 0.3
  }

  /**
   * Analyze codebase and detect routing patterns
   */
  async detectPatterns(context: {
    framework: string
    packageJson: Record<string, any>
    sampleFiles: Array<{ path: string; content: string }>
    fileStructure: string[]
  }): Promise<LLMPatternDetectionResponse> {
    const prompt = PromptTemplates.createPatternDetectionPrompt(context)

    try {
      const response = await this.client.messages.create({
        model: this.model,
        max_tokens: this.maxTokens,
        temperature: this.temperature,
        messages: [
          {
            role: 'user',
            content: prompt,
          },
        ],
      })

      // Extract text content from response
      const content = response.content[0]
      if (content.type !== 'text') {
        throw new Error('Unexpected response type from Claude')
      }

      // Parse JSON response
      const result = this.parseResponse(content.text)
      return result
    } catch (error) {
      throw new Error(`Claude API error: ${error}`)
    }
  }

  /**
   * Parse Claude response to structured format
   */
  private parseResponse(responseText: string): LLMPatternDetectionResponse {
    try {
      // Extract JSON from markdown code blocks if present
      const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/)
      const jsonText = jsonMatch ? jsonMatch[1] : responseText

      const parsed = JSON.parse(jsonText)

      // Validate response structure
      if (!parsed.framework || !parsed.routingStrategy) {
        throw new Error('Invalid response structure from Claude')
      }

      return {
        framework: parsed.framework || 'unknown',
        routingStrategy: parsed.routingStrategy || 'unknown',
        routeFiles: parsed.routeFiles || [],
        layoutComponents: parsed.layoutComponents || [],
        importAliases: parsed.importAliases || {},
        sampleRouteMappings: parsed.sampleRouteMappings || [],
        confidence: parsed.confidence || 'medium',
        reasoning: parsed.reasoning || '',
      }
    } catch (error) {
      throw new Error(`Failed to parse Claude response: ${error}`)
    }
  }

  /**
   * Validate the detected patterns with a follow-up query
   */
  async validatePatterns(
    patterns: LLMPatternDetectionResponse,
    validationContext: {
      actualFiles: string[]
      sampleImports: string[]
    }
  ): Promise<{ isValid: boolean; suggestions?: string[] }> {
    const prompt = PromptTemplates.createValidationPrompt(patterns, validationContext)

    try {
      const response = await this.client.messages.create({
        model: this.model,
        max_tokens: 1024,
        temperature: 0.1,
        messages: [
          {
            role: 'user',
            content: prompt,
          },
        ],
      })

      const content = response.content[0]
      if (content.type !== 'text') {
        return { isValid: false }
      }

      const result = JSON.parse(content.text)
      return {
        isValid: result.isValid || false,
        suggestions: result.suggestions || [],
      }
    } catch {
      return { isValid: true } // Assume valid if validation fails
    }
  }
}
