/**
 * Main entry point for route-impact-analyzer
 */

import path from 'path'
import { PatternAnalyzer } from './core/PatternAnalyzer'
import { StaticAnalyzer } from './core/StaticAnalyzer'
import { RouteTracer } from './core/RouteTracer'
import { CacheManager } from './cache/CacheManager'
import { PathResolver } from './utils/PathResolver.util'
import type {
  AnalyzeRouteImpactInput,
  AnalysisResult,
  PatternCache,
} from './types'

/**
 * Main API function to analyze route impacts
 */
export async function analyzeRouteImpact(
  input: AnalyzeRouteImpactInput
): Promise<AnalysisResult> {
  const startTime = Date.now()
  let normalizedChangedFiles: string[] = []

  try {
    // Validate input
    if (!input.codebase.path && !input.codebase.githubRepo) {
      throw new Error('Either codebase.path or codebase.githubRepo must be provided')
    }

    if (!input.changedFiles || input.changedFiles.length === 0) {
      throw new Error('No changed files provided')
    }

    // Determine project root
    const projectRoot = input.codebase.path
      ? path.resolve(input.codebase.path)
      : process.cwd()

    // Normalize changed files to project-relative paths
    normalizedChangedFiles = normalizeChangedFiles(projectRoot, input.changedFiles)

    if (normalizedChangedFiles.length === 0) {
      throw new Error('No changed files within project root')
    }

    // Configure cache
    const cacheConfig = {
      enabled: input.options?.cache?.enabled ?? true,
      provider: input.options?.cache?.provider || 'github-actions',
      ttl: input.options?.cache?.ttl || 30 * 24 * 60 * 60, // 30 days
      forceRefresh: input.options?.cache?.forceRefresh || false,
      cacheKey: input.options?.cache?.cacheKey,
    }

    const verbose = input.options?.analysis?.verbose || false

    if (verbose) {
      console.log('🚀 Route Impact Analyzer')
      console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━')
      console.log(`📁 Project: ${projectRoot}`)
      console.log(`📄 Changed files: ${normalizedChangedFiles.length}`)
      console.log('')
    }

    // Initialize cache manager
    const cacheManager = new CacheManager(projectRoot, cacheConfig)

    // Try to load cached patterns
    let patternCache: PatternCache | null = await cacheManager.load()
    let analysisType: 'full' | 'cached' = 'cached'

    if (!cacheManager.isValid(patternCache)) {
      if (verbose) {
        console.log('⚡ Cache miss - running full analysis')
      }

      // Run pattern analysis with LLM
      const patternAnalyzer = new PatternAnalyzer(
        projectRoot,
        input.options?.llm
      )

      patternCache = await patternAnalyzer.analyze({
        verbose,
        ttlSeconds: cacheConfig.ttl,
      })

      // Save to cache
      await cacheManager.save(patternCache)

      analysisType = 'full'
    } else {
      if (verbose) {
        const cacheAge = Date.now() - patternCache!.timestamp
        const days = Math.floor(cacheAge / (1000 * 60 * 60 * 24))
        console.log(`✓ Using cached patterns (${days} days old)`)
        console.log('')
      }
    }

    // Build dependency graph
    const staticAnalyzer = new StaticAnalyzer(
      projectRoot,
      patternCache!.importAliases
    )

    const graph = await staticAnalyzer.buildDependencyGraph(
      patternCache!,
      {
        maxDepth: input.options?.analysis?.maxDepth || 10,
        excludePatterns: input.options?.analysis?.excludePatterns || [],
        verbose,
      }
    )

    if (verbose) {
      const stats = staticAnalyzer.getGraphStats(graph)
      console.log(`\n📊 Dependency Graph Statistics:`)
      console.log(`  ├─ Total nodes: ${stats.totalNodes}`)
      console.log(`  ├─ Route files: ${stats.routeFiles}`)
      console.log(`  ├─ Layout components: ${stats.layoutComponents}`)
      console.log(`  ├─ Page components: ${stats.pageComponents}`)
      console.log(`  └─ Avg dependencies: ${stats.averageDependencies.toFixed(1)}`)
    }

    // Trace impacts
    const routeTracer = new RouteTracer(
      staticAnalyzer,
      patternCache!,
      input.options?.baseUrl
    )

    const impacts = routeTracer.traceImpacts(graph, normalizedChangedFiles, {
      includeLayouts: input.options?.analysis?.includeLayouts ?? true,
      maxDepth: input.options?.analysis?.maxDepth || 10,
      verbose,
    })

    // Merge and deduplicate impacts
    const mergedImpacts = RouteTracer.mergeImpacts(impacts)

    const endTime = Date.now()

    if (verbose) {
      console.log(`\n✨ Analysis complete in ${endTime - startTime}ms`)
      console.log(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`)
    }

    return {
      success: true,
      metadata: {
        timestamp: Date.now(),
        analysisType,
        framework: patternCache!.framework,
        totalFiles: normalizedChangedFiles.length,
        cacheAge: analysisType === 'cached'
          ? Date.now() - patternCache!.timestamp
          : undefined,
      },
      impacts: mergedImpacts,
    }
  } catch (error: any) {
    return {
      success: false,
      metadata: {
        timestamp: Date.now(),
        analysisType: 'full',
        framework: 'unknown',
        totalFiles: normalizedChangedFiles.length || input.changedFiles.length,
      },
      impacts: [],
      errors: [
        {
          code: 'ANALYSIS_ERROR',
          message: error.message || 'Unknown error occurred',
          stack: error.stack,
        },
      ],
    }
  }
}

function normalizeChangedFiles(projectRoot: string, files: string[]): string[] {
  const normalized = new Set<string>()

  for (const original of files) {
    if (!original) continue

    const trimmed = original.trim()
    if (!trimmed) continue

    const absolutePath = path.isAbsolute(trimmed)
      ? trimmed
      : path.resolve(projectRoot, trimmed)

    const relativePath = path.relative(projectRoot, absolutePath)

    if (!relativePath || relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
      continue
    }

    normalized.add(PathResolver.normalizePath(relativePath))
  }

  return Array.from(normalized)
}

// Export types and classes
export * from './types'
export { PatternAnalyzer } from './core/PatternAnalyzer'
export { StaticAnalyzer } from './core/StaticAnalyzer'
export { RouteTracer } from './core/RouteTracer'
export { CacheManager } from './cache/CacheManager'
export { FileSystem } from './utils/FileSystem.util'
export { ASTParser } from './utils/ASTParser.util'
export { PathResolver } from './utils/PathResolver.util'
