/**
 * Detects the frontend framework and routing library used in the codebase
 */

import { FileSystem } from '../utils/FileSystem.util'
import type { Framework, FrameworkConfig } from '../types'

export class FrameworkDetector {
  constructor(private fs: FileSystem) {}

  /**
   * Detect framework from package.json and file structure
   */
  async detect(): Promise<{
    framework: Framework
    config?: FrameworkConfig
  }> {
    const pkg = await this.fs.readPackageJson()

    if (!pkg) {
      return { framework: 'unknown' }
    }

    const allDeps = {
      ...pkg.dependencies,
      ...pkg.devDependencies,
    }

    // Check for Next.js
    if (allDeps['next']) {
      const version = this.parseVersion(allDeps['next'])
      const hasAppDir = await this.fs.fileExists('app')
      const hasPagesDir = await this.fs.fileExists('pages')

      return {
        framework: 'nextjs',
        config: {
          version,
          routerType: hasAppDir ? 'app' : 'pages',
          appDir: hasAppDir ? 'app' : undefined,
          pagesDir: hasPagesDir ? 'pages' : undefined,
        },
      }
    }

    // Check for Remix
    if (allDeps['@remix-run/react']) {
      return { framework: 'remix' }
    }

    // Check for Nuxt
    if (allDeps['nuxt']) {
      return { framework: 'nuxt' }
    }

    // Check for Vue Router
    if (allDeps['vue-router']) {
      const version = this.parseVersion(allDeps['vue-router'])
      const routerFiles = await this.fs.findFiles([
        '**/router.{ts,js}',
        '**/router/index.{ts,js}',
      ])

      return {
        framework: 'vue-router',
        config: {
          version,
          configFile: routerFiles[0] || '',
        },
      }
    }

    // Check for Angular
    if (allDeps['@angular/router']) {
      const moduleFiles = await this.fs.findFiles([
        '**/*-routing.module.ts',
        '**/app-routing.module.ts',
      ])

      return {
        framework: 'angular',
        config: {
          moduleFiles,
        },
      }
    }

    // Check for SvelteKit
    if (allDeps['@sveltejs/kit']) {
      return { framework: 'svelte-kit' }
    }

    // Check for React Router (standalone)
    if (allDeps['react-router'] || allDeps['react-router-dom']) {
      const version = this.parseVersion(
        allDeps['react-router-dom'] || allDeps['react-router']
      )

      const routeFiles = await this.fs.findFiles([
        '**/routes.{ts,tsx,js,jsx}',
        '**/router.{ts,tsx,js,jsx}',
        '**/*Router.{ts,tsx,js,jsx}',
        '**/*Routes.{ts,tsx,js,jsx}',
      ])

      // Check for TypeScript
      const isTypeScript = await this.fs.fileExists('tsconfig.json')

      return {
        framework: 'react-router',
        config: {
          version,
          configFiles: routeFiles,
          isTypeScript,
        },
      }
    }

    return { framework: 'unknown' }
  }

  /**
   * Parse version number from dependency string
   */
  private parseVersion(versionString: string): number {
    const match = versionString.match(/^[\^~]?(\d+)/)
    return match ? parseInt(match[1], 10) : 0
  }

  /**
   * Detect routing strategy (centralized, file-based, or mixed)
   */
  async detectRoutingStrategy(framework: Framework): Promise<string> {
    if (framework === 'nextjs' || framework === 'nuxt' || framework === 'svelte-kit') {
      return 'file-based'
    }

    if (framework === 'react-router' || framework === 'vue-router' || framework === 'angular') {
      // Look for centralized route config files
      const routeConfigFiles = await this.fs.findFiles([
        '**/routes.{ts,tsx,js,jsx}',
        '**/router.{ts,tsx,js,jsx}',
        '**/*Router.{ts,tsx,js,jsx}',
        '**/routing.module.ts',
      ])

      if (routeConfigFiles.length > 0) {
        return 'centralized'
      }
    }

    return 'mixed'
  }
}
