/**
 * AST parsing utilities for analyzing JavaScript/TypeScript files
 */

import * as parser from '@babel/parser'
import traverse from '@babel/traverse'
import * as t from '@babel/types'
import type { ParsedImport, ComponentInfo } from '../types'

export class ASTParser {
  /**
   * Parse file content to AST
   */
  parse(content: string, filePath: string): any {
    const isTypeScript = filePath.endsWith('.ts') || filePath.endsWith('.tsx')
    const isJSX = filePath.endsWith('.jsx') || filePath.endsWith('.tsx')

    try {
      return parser.parse(content, {
        sourceType: 'module',
        plugins: [
          isTypeScript && 'typescript',
          isJSX && 'jsx',
          'decorators-legacy',
          'classProperties',
          'dynamicImport',
          'exportDefaultFrom',
          'exportNamespaceFrom',
          'objectRestSpread',
          'optionalChaining',
          'nullishCoalescingOperator',
        ].filter(Boolean) as parser.ParserPlugin[],
      })
    } catch (error) {
      throw new Error(`Failed to parse ${filePath}: ${error}`)
    }
  }

  /**
   * Extract imports from file
   */
  extractImports(content: string, filePath: string): ParsedImport[] {
    const ast = this.parse(content, filePath)
    const imports: ParsedImport[] = []

    traverse(ast, {
      // Regular imports: import X from 'y'
      ImportDeclaration(path) {
        const source = path.node.source.value
        const specifiers: string[] = []
        const localToImported: Record<string, string> = {}
        let isDefault = false

        path.node.specifiers.forEach((spec) => {
          if (t.isImportDefaultSpecifier(spec)) {
            specifiers.push(spec.local.name)
            isDefault = true
            localToImported[spec.local.name] = 'default'
          } else if (t.isImportNamespaceSpecifier(spec)) {
            specifiers.push(`* as ${spec.local.name}`)
            localToImported[spec.local.name] = '*'
          } else if (t.isImportSpecifier(spec)) {
            specifiers.push(
              spec.imported.type === 'Identifier'
                ? spec.imported.name
                : spec.imported.value
            )
            localToImported[spec.local.name] =
              spec.imported.type === 'Identifier'
                ? spec.imported.name
                : spec.imported.value
          }
        })

        imports.push({
          source,
          specifiers,
          isDefault,
          isDynamic: false,
          localToImported: Object.keys(localToImported).length > 0
            ? localToImported
            : undefined,
        })
      },

      // Dynamic imports: import('y')
      CallExpression(path) {
        if (t.isImport(path.node.callee)) {
          const arg = path.node.arguments[0]
          if (t.isStringLiteral(arg)) {
            imports.push({
              source: arg.value,
              specifiers: [],
              isDefault: false,
              isDynamic: true,
            })
          }
        }
      },

      // Require: const x = require('y')
      VariableDeclarator(path) {
        if (
          t.isCallExpression(path.node.init) &&
          t.isIdentifier(path.node.init.callee) &&
          path.node.init.callee.name === 'require'
        ) {
          const arg = path.node.init.arguments[0]
          if (t.isStringLiteral(arg)) {
            const specifiers: string[] = []
            if (t.isIdentifier(path.node.id)) {
              specifiers.push(path.node.id.name)
            }

            imports.push({
              source: arg.value,
              specifiers,
              isDefault: true,
              isDynamic: false,
            })
          }
        }
      },
    })

    return imports
  }

  /**
   * Extract exports from file
   */
  extractExports(content: string, filePath: string): string[] {
    const ast = this.parse(content, filePath)
    const exports: string[] = []

    traverse(ast, {
      ExportNamedDeclaration(path) {
        if (path.node.declaration) {
          if (t.isFunctionDeclaration(path.node.declaration)) {
            if (path.node.declaration.id) {
              exports.push(path.node.declaration.id.name)
            }
          } else if (t.isVariableDeclaration(path.node.declaration)) {
            path.node.declaration.declarations.forEach((decl) => {
              if (t.isIdentifier(decl.id)) {
                exports.push(decl.id.name)
              }
            })
          } else if (t.isClassDeclaration(path.node.declaration)) {
            if (path.node.declaration.id) {
              exports.push(path.node.declaration.id.name)
            }
          }
        }

        path.node.specifiers?.forEach((spec) => {
          if (t.isExportSpecifier(spec)) {
            exports.push(
              spec.exported.type === 'Identifier'
                ? spec.exported.name
                : spec.exported.value
            )
          }
        })
      },

      ExportDefaultDeclaration(path) {
        exports.push('default')
      },
    })

    return exports
  }

  /**
   * Extract lazy import mappings (component name -> file path)
   */
  extractLazyImports(content: string, filePath: string): Map<string, string> {
    const ast = this.parse(content, filePath)
    const lazyImports = new Map<string, string>()

    traverse(ast, {
      VariableDeclarator(path) {
        // Look for: const ComponentName = lazy(() => import('path'))
        if (
          t.isIdentifier(path.node.id) &&
          t.isCallExpression(path.node.init)
        ) {
          const componentName = path.node.id.name
          const callExpr = path.node.init

          // Check if it's lazy(() => ...)
          if (
            t.isIdentifier(callExpr.callee) &&
            callExpr.callee.name === 'lazy'
          ) {
            // Get the arrow function argument
            const lazyArg = callExpr.arguments[0]
            if (t.isArrowFunctionExpression(lazyArg)) {
              const body = lazyArg.body

              // Check if body is import('...')
              if (t.isCallExpression(body)) {
                if (t.isImport(body.callee)) {
                  const importPath = body.arguments[0]
                  if (t.isStringLiteral(importPath)) {
                    lazyImports.set(componentName, importPath.value)
                  }
                }
              }
            }
          }
        }
      },
    })

    return lazyImports
  }

  /**
   * Extract route definitions from React Router config
   */
  extractReactRouterRoutes(content: string, filePath: string): Array<{
    path: string
    component: string
    isLazy: boolean
  }> {
    const ast = this.parse(content, filePath)
    const routes: Array<{ path: string; component: string; isLazy: boolean }> = []

    // First, extract lazy import mappings
    const lazyImports = this.extractLazyImports(content, filePath)

    traverse(ast, {
      // Look for route objects with path and element/component properties
      ObjectExpression(path) {
        let routePath: string | null = null
        let componentName: string | null = null
        let isLazy = false

        path.node.properties.forEach((prop) => {
          if (
            t.isObjectProperty(prop) &&
            t.isIdentifier(prop.key)
          ) {
            // Extract path
            if (prop.key.name === 'path' && t.isStringLiteral(prop.value)) {
              routePath = prop.value.value
            }

            // Extract component (element or component property)
            if (
              (prop.key.name === 'element' || prop.key.name === 'component')
            ) {
              if (t.isJSXElement(prop.value)) {
                // <Component />
                if (t.isJSXIdentifier(prop.value.openingElement.name)) {
                  componentName = prop.value.openingElement.name.name
                  isLazy = lazyImports.has(componentName)
                }
              } else if (t.isIdentifier(prop.value)) {
                // Component (without JSX)
                componentName = prop.value.name
                isLazy = lazyImports.has(componentName)
              } else if (t.isCallExpression(prop.value)) {
                // lazy(() => import('...'))
                isLazy = true
              }
            }
          }
        })

        if (routePath && componentName) {
          // Resolve component name to file path if it's a lazy import
          const resolvedComponent = lazyImports.get(componentName) || componentName
          routes.push({ path: routePath, component: resolvedComponent, isLazy })
        }
      },
    })

    return routes
  }

  /**
   * Check if file exports a React component
   */
  isReactComponent(content: string, filePath: string): boolean {
    try {
      const ast = this.parse(content, filePath)
      let hasReactImport = false
      let hasComponentExport = false

      traverse(ast, {
        ImportDeclaration(path) {
          if (path.node.source.value === 'react') {
            hasReactImport = true
          }
        },

        // Check for function components
        ExportDefaultDeclaration(path) {
          if (
            t.isFunctionDeclaration(path.node.declaration) ||
            t.isArrowFunctionExpression(path.node.declaration)
          ) {
            hasComponentExport = true
          }
        },

        // Check for named exports that might be components
        ExportNamedDeclaration(path) {
          if (
            path.node.declaration &&
            (t.isFunctionDeclaration(path.node.declaration) ||
              t.isVariableDeclaration(path.node.declaration))
          ) {
            hasComponentExport = true
          }
        },
      })

      return hasReactImport && hasComponentExport
    } catch {
      return false
    }
  }

  /**
   * Extract re-exports from barrel files
   * Returns a map of exported names to their source modules
   */
  extractReExports(content: string, filePath: string): Map<string, { source: string; localName: string }> {
    const ast = this.parse(content, filePath)
    const reExports = new Map<string, { source: string; localName: string }>()

    traverse(ast, {
      // Handle: export { X } from './path'
      // Handle: export { X as Y } from './path'
      // Handle: export const X = React.lazy(() => import('./path'))
      ExportNamedDeclaration(path) {
        // Case 1: Re-export from another module (export { X } from './path')
        if (path.node.source) {
          const source = path.node.source.value

          path.node.specifiers?.forEach((spec) => {
            if (t.isExportSpecifier(spec)) {
              const exportedName = spec.exported.type === 'Identifier'
                ? spec.exported.name
                : spec.exported.value
              const localName = spec.local.name

              reExports.set(exportedName, { source, localName })
            }
          })
        }

        // Case 2: Export with declaration (export const X = React.lazy(...))
        if (path.node.declaration && t.isVariableDeclaration(path.node.declaration)) {
          path.node.declaration.declarations.forEach((decl) => {
            if (t.isIdentifier(decl.id) && t.isCallExpression(decl.init)) {
              const componentName = decl.id.name
              const callExpr = decl.init

              // Check for React.lazy or lazy
              if (
                (t.isMemberExpression(callExpr.callee) &&
                  t.isIdentifier(callExpr.callee.object) &&
                  callExpr.callee.object.name === 'React' &&
                  t.isIdentifier(callExpr.callee.property) &&
                  callExpr.callee.property.name === 'lazy') ||
                (t.isIdentifier(callExpr.callee) && callExpr.callee.name === 'lazy')
              ) {
                // Get the arrow function argument
                const lazyArg = callExpr.arguments[0]
                if (t.isArrowFunctionExpression(lazyArg)) {
                  const body = lazyArg.body

                  // Check if body is import('...')
                  if (t.isCallExpression(body) && t.isImport(body.callee)) {
                    const importPath = body.arguments[0]
                    if (t.isStringLiteral(importPath)) {
                      reExports.set(componentName, {
                        source: importPath.value,
                        localName: 'default'
                      })
                    }
                  }
                }
              }
            }
          })
        }
      },

      // Handle: export * from './path'
      ExportAllDeclaration(path) {
        if (path.node.source) {
          const source = path.node.source.value
          // Mark as wildcard re-export
          reExports.set('*', { source, localName: '*' })
        }
      },
    })

    return reExports
  }

  /**
   * Extract component info (imports, exports, type)
   */
  extractComponentInfo(content: string, filePath: string): ComponentInfo {
    const imports = this.extractImports(content, filePath)
    const exports = this.extractExports(content, filePath)

    // Heuristics to determine if it's a page or layout
    const fileName = filePath.toLowerCase()
    const isPage =
      fileName.includes('/pages/') ||
      fileName.includes('/routes/') ||
      fileName.includes('/views/') ||
      fileName.endsWith('page.tsx') ||
      fileName.endsWith('page.ts')

    const isLayout =
      fileName.includes('layout') ||
      fileName.includes('wrapper') ||
      fileName.includes('container')

    return {
      filePath,
      imports,
      exports,
      isPage,
      isLayout,
    }
  }
}
