/**
 * Cache Manager - Handles pattern cache storage and retrieval
 */

import * as fs from 'fs/promises'
import * as path from 'path'
import * as crypto from 'crypto'
import type { PatternCache, CacheConfig } from '../types'

export class CacheManager {
  private cacheKey: string
  private cacheDir: string

  private static readonly CACHE_VERSION = 'v1'

  constructor(
    private projectRoot: string,
    private config: CacheConfig
  ) {
    this.cacheKey = config.cacheKey || this.generateCacheKey()
    this.cacheDir = this.getCacheDirectory()
  }

  /**
   * Load pattern cache from storage
   */
  async load(): Promise<PatternCache | null> {
    if (!this.config.enabled || this.config.forceRefresh) {
      return null
    }

    try {
      if (this.config.provider === 'github-actions') {
        return await this.loadFromGitHubActions()
      } else if (this.config.provider === 'file-system') {
        return await this.loadFromFileSystem()
      }
    } catch (error) {
      console.warn('Failed to load cache:', error)
    }

    return null
  }

  /**
   * Save pattern cache to storage
   */
  async save(cache: PatternCache): Promise<void> {
    if (!this.config.enabled) {
      return
    }

    try {
      if (this.config.provider === 'github-actions') {
        await this.saveToGitHubActions(cache)
      } else if (this.config.provider === 'file-system') {
        await this.saveToFileSystem(cache)
      }
    } catch (error) {
      console.warn('Failed to save cache:', error)
    }
  }

  /**
   * Check if cache is valid (not expired)
   */
  isValid(cache: PatternCache | null): boolean {
    if (!cache) {
      return false
    }

    // Check if expired
    if (Date.now() > cache.expiresAt) {
      return false
    }

    // Check if project root matches
    if (cache.projectRoot !== this.projectRoot) {
      return false
    }

    return true
  }

  /**
   * Load cache from GitHub Actions cache
   */
  private async loadFromGitHubActions(): Promise<PatternCache | null> {
    try {
      // Try to use @actions/cache if available
      const actionsCache = await import('@actions/cache')

      const cachePath = path.join(this.cacheDir, 'pattern-cache.json')

      // Restore cache
      const restoredKey = await actionsCache.restoreCache(
        [cachePath],
        this.cacheKey,
        [] // No restore keys - exact match only
      )

      if (!restoredKey) {
        return null
      }

      // Read cache file
      const cacheContent = await fs.readFile(cachePath, 'utf-8')
      return JSON.parse(cacheContent)
    } catch (error) {
      // GitHub Actions cache not available - fall back to file system
      return await this.loadFromFileSystem()
    }
  }

  /**
   * Save cache to GitHub Actions cache
   */
  private async saveToGitHubActions(cache: PatternCache): Promise<void> {
    try {
      // Try to use @actions/cache if available
      const actionsCache = await import('@actions/cache')

      // Ensure cache directory exists
      await fs.mkdir(this.cacheDir, { recursive: true })

      const cachePath = path.join(this.cacheDir, 'pattern-cache.json')

      // Write cache file
      await fs.writeFile(cachePath, JSON.stringify(cache, null, 2), 'utf-8')

      // Save to GitHub Actions cache
      await actionsCache.saveCache([cachePath], this.cacheKey)
    } catch (error) {
      // GitHub Actions cache not available - fall back to file system
      await this.saveToFileSystem(cache)
    }
  }

  /**
   * Load cache from file system
   */
  private async loadFromFileSystem(): Promise<PatternCache | null> {
    const cachePath = path.join(this.cacheDir, 'pattern-cache.json')

    try {
      const cacheContent = await fs.readFile(cachePath, 'utf-8')
      return JSON.parse(cacheContent)
    } catch {
      return null
    }
  }

  /**
   * Save cache to file system
   */
  private async saveToFileSystem(cache: PatternCache): Promise<void> {
    // Ensure cache directory exists
    await fs.mkdir(this.cacheDir, { recursive: true })

    const cachePath = path.join(this.cacheDir, 'pattern-cache.json')

    await fs.writeFile(cachePath, JSON.stringify(cache, null, 2), 'utf-8')
  }

  /**
   * Generate cache key based on project characteristics
   */
  private generateCacheKey(): string {
    const hash = crypto.createHash('sha256')

    // Include project path in hash so caches are per-repo
    hash.update(this.projectRoot)

    // Include cache configuration that affects cache semantics
    hash.update(JSON.stringify({
      provider: this.config.provider,
      ttl: this.config.ttl ?? null,
      version: CacheManager.CACHE_VERSION,
    }))

    return `route-impact-cache-${hash.digest('hex').slice(0, 16)}`
  }

  /**
   * Get cache directory based on environment
   */
  private getCacheDirectory(): string {
    // Use GitHub Actions runner temp directory if available
    if (process.env.RUNNER_TEMP) {
      return path.join(process.env.RUNNER_TEMP, 'route-impact-cache')
    }

    // Use system temp directory
    const tmpDir = process.env.TMPDIR || process.env.TMP || '/tmp'
    return path.join(tmpDir, 'route-impact-cache')
  }

  /**
   * Clear cache
   */
  async clear(): Promise<void> {
    try {
      const cachePath = path.join(this.cacheDir, 'pattern-cache.json')
      await fs.unlink(cachePath)
    } catch {
      // Ignore errors if cache doesn't exist
    }
  }

  /**
   * Get cache statistics
   */
  async getStats(): Promise<{
    exists: boolean
    size?: number
    age?: number
    expiresIn?: number
  }> {
    const cachePath = path.join(this.cacheDir, 'pattern-cache.json')

    try {
      const stats = await fs.stat(cachePath)
      const cache = await this.load()

      return {
        exists: true,
        size: stats.size,
        age: cache ? Date.now() - cache.timestamp : undefined,
        expiresIn: cache ? cache.expiresAt - Date.now() : undefined,
      }
    } catch {
      return { exists: false }
    }
  }
}
