/**
 * Route Tracer - Determines which routes are impacted by file changes
 */

import type {
  DependencyGraph,
  PatternCache,
  RouteImpact,
  ImpactReason,
  Confidence,
} from '../types'
import { StaticAnalyzer } from './StaticAnalyzer'

export class RouteTracer {
  constructor(
    private staticAnalyzer: StaticAnalyzer,
    private patternCache: PatternCache,
    private baseUrl?: string
  ) {}

  /**
   * Trace changed files to impacted routes
   */
  traceImpacts(
    graph: DependencyGraph,
    changedFiles: string[],
    options: {
      includeLayouts?: boolean
      maxDepth?: number
      verbose?: boolean
    } = {}
  ): RouteImpact[] {
    const {
      includeLayouts = true,
      maxDepth = 10,
      verbose = false,
    } = options

    if (verbose) {
      console.log(`\n🎯 Tracing impacts for ${changedFiles.length} changed files...`)
    }

    const impacts: RouteImpact[] = []

    for (const changedFile of changedFiles) {
      if (verbose) {
        console.log(`\n  📄 ${changedFile}`)
      }

      const impact = this.traceFileImpact(
        graph,
        changedFile,
        { includeLayouts, maxDepth, verbose }
      )

      if (impact) {
        impacts.push(impact)
        if (verbose) {
          console.log(`    └─ ${impact.impactedRoutes.length} routes impacted (${impact.reason})`)
        }
      }
    }

    return impacts
  }

  /**
   * Trace impact for a single file
   */
  private traceFileImpact(
    graph: DependencyGraph,
    changedFile: string,
    options: {
      includeLayouts?: boolean
      maxDepth?: number
      verbose?: boolean
    }
  ): RouteImpact | null {
    const { includeLayouts = true, maxDepth = 10 } = options
    const traversalDepth = Math.max(1, maxDepth)

    // Check if file is in the graph
    if (!graph.nodes.has(changedFile)) {
      // File not in dependency graph - might be a new file or not part of the app
      return null
    }

    const node = graph.nodes.get(changedFile)!

    // Case 1: Direct route component change
    if (node.isPageComponent) {
      const mapping = this.patternCache.routeMappings.find(
        m => m.component === changedFile
      )

      if (mapping) {
        return {
          changedFile,
          impactedRoutes: [this.formatRoute(mapping.path)],
          reason: 'direct',
          confidence: 'high',
        }
      }
    }

    // Case 2: Layout component change (affects all routes that use it)
    if (includeLayouts && node.isLayoutComponent) {
      const affectedRoutes = this.patternCache.routeMappings
        .filter(mapping => mapping.layouts.includes(changedFile))
        .map(mapping => this.formatRoute(mapping.path))

      if (affectedRoutes.length > 0) {
        return {
          changedFile,
          impactedRoutes: affectedRoutes,
          reason: 'layout',
          confidence: 'high',
        }
      }
    }

    // Case 3: Shared component/utility - find which routes depend on it
    // Use caller-provided depth cap to avoid over-propagation through shared utilities
    const dependents = this.staticAnalyzer.findDependents(
      graph,
      changedFile,
      traversalDepth
    )

    // Find which routes are affected
    const impactedRoutes = new Set<string>()
    let reason: ImpactReason = 'shared-component'
    let confidence: Confidence = 'medium'

    // Get direct dependents only (depth 1) for layout and direct page checks
    const directDependents = this.staticAnalyzer.findDependents(
      graph,
      changedFile,
      1 // Only direct imports
    )

    // Count direct page and layout dependencies to determine classification
    let hasDirectPageDependents = false
    let hasDirectLayoutDependents = false

    for (const dependent of dependents) {
      const depNode = graph.nodes.get(dependent)

      // Only count page components that DIRECTLY depend on this file
      // This prevents over-propagation through shared utilities
      if (depNode?.isPageComponent && directDependents.has(dependent)) {
        const mapping = this.patternCache.routeMappings.find(
          m => m.component === dependent
        )

        if (mapping) {
          impactedRoutes.add(this.formatRoute(mapping.path))
          hasDirectPageDependents = true
        }
      }

      // Only propagate layout impact if this is a DIRECT dependent
      // This prevents transitive layout propagation through page components
      if (depNode?.isLayoutComponent && directDependents.has(dependent)) {
        // This dependent is a layout - affects all routes using it
        const layoutRoutes = this.patternCache.routeMappings
          .filter(m => m.layouts.includes(dependent))
          .map(m => this.formatRoute(m.path))

        layoutRoutes.forEach(route => impactedRoutes.add(route))
        hasDirectLayoutDependents = true
      }
    }

    // Determine reason based on dependency pattern:
    // - If ONLY layouts depend on it (no direct pages) → 'layout'
    // - If both layouts and pages depend on it → 'shared-component'
    // - If only pages depend on it → 'shared-component'
    if (hasDirectLayoutDependents && !hasDirectPageDependents) {
      reason = 'layout'
    }

    if (impactedRoutes.size === 0) {
      return null
    }

    // Adjust confidence based on dependency depth
    const maxDependencyDepth = this.getMaxDependencyDepth(
      graph,
      changedFile,
      dependents
    )

    if (maxDependencyDepth === 1) {
      confidence = 'high'
    } else if (maxDependencyDepth <= 3) {
      confidence = 'medium'
    } else {
      confidence = 'low'
    }

    return {
      changedFile,
      impactedRoutes: Array.from(impactedRoutes).sort(),
      reason,
      confidence,
    }
  }

  /**
   * Format route path with base URL if provided
   */
  private formatRoute(path: string): string {
    if (!this.baseUrl) {
      return path
    }

    // Ensure path starts with /
    const normalizedPath = path.startsWith('/') ? path : `/${path}`

    // Combine base URL and path
    const baseUrl = this.baseUrl.replace(/\/$/, '') // Remove trailing slash
    return `${baseUrl}${normalizedPath}`
  }

  /**
   * Get maximum dependency depth from changed file to impacted routes
   */
  private getMaxDependencyDepth(
    graph: DependencyGraph,
    startFile: string,
    dependents: Set<string>
  ): number {
    let maxDepth = 0

    for (const dependent of dependents) {
      const depth = this.calculateDepth(graph, startFile, dependent)
      maxDepth = Math.max(maxDepth, depth)
    }

    return maxDepth
  }

  /**
   * Calculate shortest path depth between two files
   */
  private calculateDepth(
    graph: DependencyGraph,
    from: string,
    to: string
  ): number {
    const queue: Array<{ file: string; depth: number }> = [
      { file: from, depth: 0 },
    ]
    const visited = new Set<string>()

    while (queue.length > 0) {
      const { file, depth } = queue.shift()!

      if (file === to) {
        return depth
      }

      if (visited.has(file)) {
        continue
      }

      visited.add(file)

      const node = graph.nodes.get(file)
      if (!node) {
        continue
      }

      for (const dependent of node.dependents) {
        if (!visited.has(dependent)) {
          queue.push({ file: dependent, depth: depth + 1 })
        }
      }
    }

    return Infinity
  }

  /**
   * Merge and deduplicate impacts
   */
  static mergeImpacts(impacts: RouteImpact[]): RouteImpact[] {
    const merged = new Map<string, RouteImpact>()

    for (const impact of impacts) {
      const existing = merged.get(impact.changedFile)

      if (!existing) {
        merged.set(impact.changedFile, { ...impact })
      } else {
        // Merge routes and update confidence/reason if needed
        const allRoutes = new Set([
          ...existing.impactedRoutes,
          ...impact.impactedRoutes,
        ])

        // Take the highest confidence
        const confidence =
          this.compareConfidence(existing.confidence, impact.confidence) >= 0
            ? existing.confidence
            : impact.confidence

        // Prefer 'direct' > 'layout' > 'shared-component'
        const reason = this.selectBestReason(existing.reason, impact.reason)

        merged.set(impact.changedFile, {
          changedFile: impact.changedFile,
          impactedRoutes: Array.from(allRoutes).sort(),
          reason,
          confidence,
        })
      }
    }

    return Array.from(merged.values())
  }

  /**
   * Compare confidence levels
   */
  private static compareConfidence(a: Confidence, b: Confidence): number {
    const order: Record<Confidence, number> = {
      high: 3,
      medium: 2,
      low: 1,
    }

    return order[a] - order[b]
  }

  /**
   * Select best impact reason
   */
  private static selectBestReason(
    a: ImpactReason,
    b: ImpactReason
  ): ImpactReason {
    const order: Record<ImpactReason, number> = {
      direct: 3,
      layout: 2,
      'shared-component': 1,
    }

    return order[a] >= order[b] ? a : b
  }
}
