/**
 * Pattern Analyzer - Uses LLM to detect routing patterns in codebase
 */

import { FileSystem } from '../utils/FileSystem.util'
import { ASTParser } from '../utils/ASTParser.util'
import { PathResolver } from '../utils/PathResolver.util'
import { FrameworkDetector } from './FrameworkDetector'
import { ClaudeProvider } from '../llm/ClaudeProvider'
import type {
  LLMConfig,
  PatternCache,
  Framework,
  ParsedImport,
  RouteMapping,
  LLMPatternDetectionResponse,
} from '../types'

export class PatternAnalyzer {
  private fs: FileSystem
  private astParser: ASTParser
  private pathResolver: PathResolver
  private frameworkDetector: FrameworkDetector
  private llm?: ClaudeProvider

  constructor(projectRoot: string, llmConfig?: LLMConfig) {
    this.fs = new FileSystem(projectRoot)
    this.astParser = new ASTParser()
    this.pathResolver = new PathResolver(projectRoot)
    this.frameworkDetector = new FrameworkDetector(this.fs)

    if (llmConfig) {
      this.llm = new ClaudeProvider(llmConfig)
    }
  }

  /**
   * Analyze codebase and generate pattern cache
   */
  async analyze(options: {
    verbose?: boolean
    ttlSeconds?: number
  } = {}): Promise<PatternCache> {
    const { verbose = false, ttlSeconds } = options

    if (verbose) {
      console.log('🔍 Starting pattern analysis...')
    }

    // Step 1: Detect framework
    if (verbose) console.log('  ├─ Detecting framework...')
    const { framework, config: frameworkConfig } = await this.frameworkDetector.detect()

    if (verbose) console.log(`  ├─ Framework: ${framework}`)

    // Step 2: Gather context for LLM
    if (verbose) console.log('  ├─ Gathering codebase context...')
    const context = await this.gatherCodebaseContext(framework)

    // Step 3: Get import aliases from tsconfig
    if (verbose) console.log('  ├─ Parsing import aliases...')
    const importAliases = await this.extractImportAliases()

    this.pathResolver.setAliases(importAliases)

    // Step 4: Use LLM to detect patterns (if available)
    let llmResponse: LLMPatternDetectionResponse
    if (this.llm) {
      if (verbose) console.log('  ├─ Analyzing with Claude AI...')
      llmResponse = await this.llm.detectPatterns(context)

      if (verbose) {
        console.log(`  ├─ Confidence: ${llmResponse.confidence}`)
        console.log(`  └─ ${llmResponse.reasoning}`)
      }
    } else {
      if (verbose) console.log('  ├─ Using fallback heuristics (no LLM)...')
      llmResponse = await this.fallbackAnalysis(framework, context)
    }

    // Step 5: Build pattern cache
    const cacheTtlMs = (ttlSeconds ?? 30 * 24 * 60 * 60) * 1000

    const patternCache: PatternCache = {
      version: '1.0.0',
      timestamp: Date.now(),
      expiresAt: Date.now() + cacheTtlMs,
      framework: llmResponse.framework,
      routingStrategy: llmResponse.routingStrategy,
      routeFiles: this.normalizeProjectPaths(llmResponse.routeFiles),
      layoutComponents: this.normalizeProjectPaths(llmResponse.layoutComponents),
      routeMappings: (llmResponse.sampleRouteMappings || []).map(
        (mapping): RouteMapping => ({
          ...mapping,
          component: mapping.component
            ? this.normalizeProjectPath(mapping.component)
            : mapping.component,
          layouts: this.normalizeProjectPaths(mapping.layouts || []),
        })
      ),
      importAliases: { ...importAliases, ...llmResponse.importAliases },
      projectRoot: this.fs['projectRoot'],
    }

    // Step 6: Validate and enrich pattern cache
    if (verbose) console.log('\n✓ Pattern analysis complete!')
    return this.enrichPatternCache(patternCache)
  }

  /**
   * Gather context about the codebase for LLM analysis
   */
  private async gatherCodebaseContext(framework: Framework): Promise<{
    framework: string
    packageJson: Record<string, any>
    sampleFiles: Array<{ path: string; content: string }>
    fileStructure: string[]
  }> {
    // Read package.json
    const packageJson = (await this.fs.readPackageJson()) || {}

    // Get file structure
    const allFiles = await this.fs.findFiles([
      '**/*.{ts,tsx,js,jsx,vue}',
    ], {
      ignore: [
        '**/node_modules/**',
        '**/dist/**',
        '**/build/**',
        '**/.next/**',
        '**/coverage/**',
      ],
    })

    // Find route-related files
    const routeFilePatterns = this.getRouteFilePatterns(framework)
    const routeFiles = await this.fs.findFiles(routeFilePatterns)

    // Read sample route files (max 15 to capture all modular routers)
    const sampleFiles: Array<{ path: string; content: string }> = []
    for (const filePath of routeFiles.slice(0, 15)) {
      const fileInfo = await this.fs.readFile(filePath)
      if (fileInfo.exists) {
        sampleFiles.push({
          path: filePath,
          content: fileInfo.content,
        })
      }
    }

    // If no route files found, sample some pages
    if (sampleFiles.length === 0) {
      const pageFiles = await this.fs.findFiles([
        '**/pages/**/*.{ts,tsx,js,jsx}',
        '**/app/**/*.{ts,tsx,js,jsx}',
        '**/src/pages/**/*.{ts,tsx,js,jsx}',
      ])

      for (const filePath of pageFiles.slice(0, 3)) {
        const fileInfo = await this.fs.readFile(filePath)
        if (fileInfo.exists) {
          sampleFiles.push({
            path: filePath,
            content: fileInfo.content,
          })
        }
      }
    }

    return {
      framework,
      packageJson,
      sampleFiles,
      fileStructure: allFiles,
    }
  }

  /**
   * Extract import aliases from tsconfig/jsconfig
   */
  private async extractImportAliases(): Promise<Record<string, string>> {
    const tsConfig = await this.fs.readTsConfig()

    if (!tsConfig?.compilerOptions?.paths) {
      return {}
    }

    const baseUrl = tsConfig.compilerOptions.baseUrl || '.'
    return PathResolver.parseTsConfigPaths(
      tsConfig.compilerOptions.paths,
      baseUrl
    )
  }

  /**
   * Get file patterns for route files based on framework
   */
  private getRouteFilePatterns(framework: Framework): string[] {
    const patterns: Record<Framework, string[]> = {
      'react-router': [
        '**/routes.{ts,tsx,js,jsx}',
        '**/router.{ts,tsx,js,jsx}',
        '**/*Router.{ts,tsx,js,jsx}',
        '**/*Routes.{ts,tsx,js,jsx}',
        '**/*Router/**/*.{ts,tsx,js,jsx}',  // Added to catch modular routers
        '**/routes/**/*.{ts,tsx,js,jsx}',
      ],
      'nextjs': [
        'pages/**/*.{ts,tsx,js,jsx}',
        'app/**/*.{ts,tsx,js,jsx}',
      ],
      'vue-router': [
        '**/router.{ts,js}',
        '**/router/index.{ts,js}',
        '**/routes.{ts,js}',
      ],
      'angular': [
        '**/*-routing.module.ts',
        '**/app-routing.module.ts',
      ],
      'remix': [
        'app/routes/**/*.{ts,tsx,js,jsx}',
      ],
      'nuxt': [
        'pages/**/*.vue',
      ],
      'svelte-kit': [
        'src/routes/**/*.svelte',
      ],
      'unknown': [
        '**/routes/**/*.{ts,tsx,js,jsx}',
        '**/pages/**/*.{ts,tsx,js,jsx}',
      ],
    }

    return patterns[framework] || patterns['unknown']
  }

  /**
   * Fallback analysis using heuristics when LLM is not available
   */
  private async fallbackAnalysis(
    framework: Framework,
    context: {
      framework: string
      packageJson: Record<string, any>
      sampleFiles: Array<{ path: string; content: string }>
      fileStructure: string[]
    }
  ): Promise<LLMPatternDetectionResponse> {
    const routeFiles = context.sampleFiles.map(f => f.path)

    // Simple heuristic detection of layout components
    const layoutComponents = context.fileStructure.filter(file =>
      file.toLowerCase().includes('layout') ||
      file.toLowerCase().includes('wrapper') ||
      file.toLowerCase().includes('topbar') ||
      file.toLowerCase().includes('sidebar')
    ).slice(0, 5)

    return {
      framework,
      routingStrategy: framework === 'nextjs' || framework === 'nuxt' ? 'file-based' : 'centralized',
      routeFiles,
      layoutComponents,
      importAliases: {},
      sampleRouteMappings: [],
      confidence: 'low',
      reasoning: 'Fallback analysis without LLM - patterns detected using heuristics',
    }
  }

  /**
   * Enrich pattern cache with additional analysis
   */
  private async enrichPatternCache(cache: PatternCache): Promise<PatternCache> {
    // Scan all route files to build comprehensive route mappings
    const allRouteMappings = [...cache.routeMappings]
    const componentResolver = await this.buildComponentResolver(cache.routeFiles)
    const componentSearchCache = new Map<string, string | null>()
    const normalizedLayouts = this.normalizeProjectPaths(cache.layoutComponents)

    for (const routeFile of cache.routeFiles) {
      const fileInfo = await this.fs.readFile(routeFile)
      if (!fileInfo.exists) continue

      let imports: ParsedImport[] = []
      try {
        imports = this.astParser.extractImports(fileInfo.content, routeFile)
      } catch {
        // Skip import extraction errors but continue to try parsing routes
      }

      const importResolution = await this.buildImportResolution(routeFile, imports)

      try {
        const routes = this.astParser.extractReactRouterRoutes(
          fileInfo.content,
          routeFile
        )

        for (const route of routes) {
          const resolvedComponent = await this.resolveComponentPath(
            route.component,
            routeFile,
            componentResolver,
            importResolution,
            componentSearchCache
          )

          if (!resolvedComponent) {
            continue
          }

          const existingIndex = allRouteMappings.findIndex(m => m.path === route.path)

          if (existingIndex >= 0) {
            const existing = allRouteMappings[existingIndex]
            allRouteMappings[existingIndex] = {
              ...existing,
              component: resolvedComponent,
              isLazy: existing.isLazy || route.isLazy,
              layouts: this.mergeLayouts(existing.layouts, normalizedLayouts),
            }
          } else {
            allRouteMappings.push({
              path: route.path,
              component: resolvedComponent,
              isLazy: route.isLazy,
              layouts: normalizedLayouts,
            })
          }
        }
      } catch {
        // Skip files that can't be parsed
      }
    }

    return {
      ...cache,
      routeMappings: allRouteMappings,
    }
  }

  /**
   * Build a map of component names to actual file paths by scanning barrel exports
   */
  private async buildComponentResolver(routeFiles: string[]): Promise<Map<string, string>> {
    const resolver = new Map<string, string>()

    // Find potential barrel export files by looking at imports in route files
    const barrelFiles = new Set<string>()

    for (const routeFile of routeFiles) {
      const fileInfo = await this.fs.readFile(routeFile)
      if (!fileInfo.exists) continue

      try {
        const imports = this.astParser.extractImports(fileInfo.content, routeFile)

        for (const imp of imports) {
          // Check if this import looks like a barrel export
          if (imp.source.includes('/pages') ||
              imp.source.endsWith('/pages') ||
              imp.source === 'src/pages') {

            // Resolve the import to an actual file
            const resolved = this.pathResolver.resolve(imp.source, routeFile)
            if (resolved) {
              barrelFiles.add(this.normalizeProjectPath(resolved))
            }
          }
        }
      } catch {
        // Skip files that can't be parsed
      }
    }

    // Now scan each barrel file and extract component name → file path mappings
    for (const barrelFile of barrelFiles) {
      const fileInfo = await this.fs.readFile(barrelFile)
      if (!fileInfo.exists) continue

      try {
        const reExports = this.astParser.extractReExports(fileInfo.content, barrelFile)

        for (const [componentName, reExport] of reExports.entries()) {
          if (componentName !== '*') {
            // Resolve the source to an actual file path
            const resolved = this.pathResolver.resolve(reExport.source, barrelFile)
            if (resolved) {
              const relativePath = this.normalizeProjectPath(resolved)
              resolver.set(componentName, relativePath)
            }
          }
        }
      } catch {
        // Skip files that can't be parsed
      }
    }

    return resolver
  }

  private mergeLayouts(
    ...layoutLists: Array<string[] | undefined>
  ): string[] {
    const combined: string[] = []
    for (const list of layoutLists) {
      if (!list) continue
      combined.push(...list)
    }
    return this.normalizeProjectPaths(combined)
  }

  private normalizeProjectPath(filePath: string): string {
    return PathResolver.normalizePath(this.fs.getRelativePath(filePath))
  }

  private normalizeProjectPaths(paths: string[] = []): string[] {
    const seen = new Set<string>()
    const normalized: string[] = []

    for (const raw of paths ?? []) {
      if (!raw) continue
      const value = this.normalizeProjectPath(raw)
      if (!seen.has(value)) {
        seen.add(value)
        normalized.push(value)
      }
    }

    return normalized
  }

  private async buildImportResolution(
    routeFile: string,
    imports: ParsedImport[]
  ): Promise<Map<string, string>> {
    const resolution = new Map<string, string>()

    for (const imp of imports) {
      const resolved = this.pathResolver.resolve(imp.source, routeFile)
      if (!resolved) {
        continue
      }

      const relativePath = this.normalizeProjectPath(resolved)

      const localNames = Object.keys(imp.localToImported ?? {})
      for (const localName of localNames) {
        if (localName) {
          resolution.set(localName, relativePath)
        }
      }

      for (const specifier of imp.specifiers) {
        const cleanSpecifier = specifier.replace(/^[*]\s+as\s+/i, '').trim()
        if (cleanSpecifier && !resolution.has(cleanSpecifier)) {
          resolution.set(cleanSpecifier, relativePath)
        }
      }

      if (imp.isDefault && imp.specifiers.length === 0 && localNames.length === 0) {
        resolution.set('default', relativePath)
      }
    }

    return resolution
  }

  private async resolveComponentPath(
    component: string,
    routeFile: string,
    componentResolver: Map<string, string>,
    importResolution: Map<string, string>,
    searchCache: Map<string, string | null>
  ): Promise<string | null> {
    const candidate = component?.trim()
    if (!candidate) {
      return null
    }

    // If the component already looks like a path, resolve relative to the route file
    if (candidate.includes('/') || candidate.includes('\\')) {
      const resolved = this.pathResolver.resolve(candidate, routeFile)
      if (resolved) {
        return this.normalizeProjectPath(resolved)
      }
    }

    const viaBarrel = componentResolver.get(candidate)
    if (viaBarrel) {
      return this.normalizeProjectPath(viaBarrel)
    }

    const viaImport = importResolution.get(candidate)
    if (viaImport) {
      return this.normalizeProjectPath(viaImport)
    }

    const directResolution = this.pathResolver.resolve(candidate, routeFile)
    if (directResolution) {
      return this.normalizeProjectPath(directResolution)
    }

    return await this.searchComponentByName(candidate, searchCache)
  }

  private async searchComponentByName(
    componentName: string,
    cache: Map<string, string | null>
  ): Promise<string | null> {
    if (cache.has(componentName)) {
      return cache.get(componentName) ?? null
    }

    const patterns = [
      `**/${componentName}.{ts,tsx,js,jsx}`,
      `**/${componentName}/index.{ts,tsx,js,jsx}`,
    ]

    for (const pattern of patterns) {
      const matches = await this.fs.findFiles(pattern)
      if (matches.length > 0) {
        const normalized = this.normalizeProjectPath(matches[0])
        cache.set(componentName, normalized)
        return normalized
      }
    }

    cache.set(componentName, null)
    return null
  }
}
