/**
 * File system utilities for reading and analyzing codebase files
 */

import * as fs from 'fs/promises'
import * as path from 'path'
import fg from 'fast-glob'
import type { FileInfo } from '../types'

export class FileSystem {
  constructor(private projectRoot: string) {}

  /**
   * Read file content
   */
  async readFile(filePath: string): Promise<FileInfo> {
    const fullPath = path.resolve(this.projectRoot, filePath)

    try {
      const exists = await this.fileExists(filePath)
      if (!exists) {
        return { path: filePath, content: '', exists: false }
      }

      const content = await fs.readFile(fullPath, 'utf-8')
      return { path: filePath, content, exists: true }
    } catch (error) {
      return { path: filePath, content: '', exists: false }
    }
  }

  /**
   * Check if file exists
   */
  async fileExists(filePath: string): Promise<boolean> {
    const fullPath = path.resolve(this.projectRoot, filePath)
    try {
      await fs.access(fullPath)
      return true
    } catch {
      return false
    }
  }

  /**
   * Find files matching glob patterns
   */
  async findFiles(patterns: string | string[], options?: {
    ignore?: string[]
    cwd?: string
  }): Promise<string[]> {
    const cwd = options?.cwd || this.projectRoot

    const files = await fg(patterns, {
      cwd,
      ignore: options?.ignore || [
        '**/node_modules/**',
        '**/dist/**',
        '**/build/**',
        '**/.git/**',
        '**/coverage/**',
      ],
      dot: false,
      absolute: false,
    })

    return files
  }

  /**
   * Read package.json
   */
  async readPackageJson(): Promise<Record<string, any> | null> {
    const packageJsonPath = path.join(this.projectRoot, 'package.json')

    try {
      const content = await fs.readFile(packageJsonPath, 'utf-8')
      return JSON.parse(content)
    } catch {
      return null
    }
  }

  /**
   * Read tsconfig.json or jsconfig.json
   */
  async readTsConfig(): Promise<Record<string, any> | null> {
    // Try tsconfig.json first
    let configPath = path.join(this.projectRoot, 'tsconfig.json')

    try {
      const content = await fs.readFile(configPath, 'utf-8')
      // Remove comments (simple approach, may need improvement)
      const cleaned = content.replace(/\/\*[\s\S]*?\*\/|\/\/.*/g, '')
      return JSON.parse(cleaned)
    } catch {
      // Try jsconfig.json
      configPath = path.join(this.projectRoot, 'jsconfig.json')
      try {
        const content = await fs.readFile(configPath, 'utf-8')
        const cleaned = content.replace(/\/\*[\s\S]*?\*\/|\/\/.*/g, '')
        return JSON.parse(cleaned)
      } catch {
        return null
      }
    }
  }

  /**
   * Get relative path from project root
   */
  getRelativePath(filePath: string): string {
    return path.relative(this.projectRoot, path.resolve(this.projectRoot, filePath))
  }

  /**
   * Resolve absolute path
   */
  resolvePath(...paths: string[]): string {
    return path.resolve(this.projectRoot, ...paths)
  }

  /**
   * Check if path is inside project root
   */
  isInProject(filePath: string): boolean {
    const relative = path.relative(this.projectRoot, path.resolve(filePath))
    return !relative.startsWith('..') && !path.isAbsolute(relative)
  }

  /**
   * Find package.json dependencies
   */
  async getDependencies(): Promise<{
    dependencies: string[]
    devDependencies: string[]
  }> {
    const pkg = await this.readPackageJson()

    if (!pkg) {
      return { dependencies: [], devDependencies: [] }
    }

    return {
      dependencies: Object.keys(pkg.dependencies || {}),
      devDependencies: Object.keys(pkg.devDependencies || {}),
    }
  }
}
