/**
 * Static Analyzer - Builds dependency graph and analyzes code relationships
 */

import { FileSystem } from '../utils/FileSystem.util'
import { ASTParser } from '../utils/ASTParser.util'
import { PathResolver } from '../utils/PathResolver.util'
import type { DependencyGraph, DependencyNode, PatternCache, ParsedImport } from '../types'

export class StaticAnalyzer {
  private fs: FileSystem
  private astParser: ASTParser
  private pathResolver: PathResolver

  constructor(
    projectRoot: string,
    importAliases: Record<string, string> = {}
  ) {
    this.fs = new FileSystem(projectRoot)
    this.astParser = new ASTParser()
    this.pathResolver = new PathResolver(projectRoot, importAliases)
  }

  /**
   * Build dependency graph from pattern cache
   */
  async buildDependencyGraph(
    patternCache: PatternCache,
    options: {
      maxDepth?: number
      excludePatterns?: string[]
      verbose?: boolean
    } = {}
  ): Promise<DependencyGraph> {
    const { maxDepth = 10, excludePatterns = [], verbose = false } = options

    if (verbose) {
      console.log('📊 Building dependency graph...')
    }

    const graph: DependencyGraph = {
      nodes: new Map(),
      routes: new Map(),
    }

    // Add route mappings to graph
    for (const mapping of patternCache.routeMappings) {
      graph.routes.set(mapping.component, mapping)
    }

    // Start with all route files and layout components
    const startFiles = Array.from(new Set(
      [
        ...patternCache.routeFiles,
        ...patternCache.layoutComponents,
        ...patternCache.routeMappings.map(m => m.component),
      ].filter((file): file is string => Boolean(file))
    ))

    // Build graph recursively
    const visited = new Set<string>()
    const queue: Array<{ file: string; depth: number }> = startFiles.map(f => ({
      file: f,
      depth: 0,
    }))

    while (queue.length > 0) {
      const { file, depth } = queue.shift()!

      if (visited.has(file) || depth > maxDepth) {
        continue
      }

      visited.add(file)

      // Skip excluded patterns
      if (this.shouldExclude(file, excludePatterns)) {
        continue
      }

      // Read and parse file
      const fileInfo = await this.fs.readFile(file)
      if (!fileInfo.exists) {
        continue
      }

      try {
        // Extract imports
        const imports = this.astParser.extractImports(fileInfo.content, file)

        // Resolve import paths
        const resolvedDependencies: string[] = []
        for (const imp of imports) {
          if (this.pathResolver.isExternalImport(imp.source)) {
            continue // Skip external packages
          }

          const resolved = this.pathResolver.resolve(imp.source, file)
          if (resolved && this.fs.isInProject(resolved)) {
            const relativePath = this.fs.getRelativePath(resolved)

            // Check if this is a barrel export and resolve the actual source files
            const actualSources = await this.resolveBarrelExport(
              relativePath,
              imp.specifiers
            )

            if (actualSources.length > 0) {
              // Barrel export resolved - add actual source files
              for (const actualSource of actualSources) {
                resolvedDependencies.push(actualSource)

                // Add to queue for further processing
                if (!visited.has(actualSource)) {
                  queue.push({ file: actualSource, depth: depth + 1 })
                }
              }
            } else {
              // Not a barrel export or couldn't resolve - add as-is
              resolvedDependencies.push(relativePath)

              // Add to queue for further processing
              if (!visited.has(relativePath)) {
                queue.push({ file: relativePath, depth: depth + 1 })
              }
            }
          }
        }

        // Create dependency node
        const node: DependencyNode = {
          filePath: file,
          dependencies: resolvedDependencies,
          dependents: [],
          isRouteFile: patternCache.routeFiles.includes(file),
          isLayoutComponent: patternCache.layoutComponents.includes(file),
          isPageComponent: patternCache.routeMappings.some(m => m.component === file),
        }

        graph.nodes.set(file, node)

        if (verbose && depth === 0) {
          console.log(`  ├─ Processed: ${file}`)
        }
      } catch (error) {
        if (verbose) {
          console.log(`  ├─ Skipped (parse error): ${file}`)
        }
      }
    }

    // Build reverse dependencies (dependents)
    this.buildReverseDependencies(graph)

    if (verbose) {
      console.log(`  └─ Graph built: ${graph.nodes.size} nodes`)
    }

    return graph
  }

  /**
   * Build reverse dependencies (which files depend on each file)
   */
  private buildReverseDependencies(graph: DependencyGraph): void {
    for (const [filePath, node] of graph.nodes) {
      for (const dependency of node.dependencies) {
        const depNode = graph.nodes.get(dependency)
        if (depNode && !depNode.dependents.includes(filePath)) {
          depNode.dependents.push(filePath)
        }
      }
    }
  }

  /**
   * Resolve barrel export to actual source files
   * Handles patterns like: export const X = React.lazy(() => import('./path'))
   * And: export { X } from './path'
   */
  private async resolveBarrelExport(
    barrelFile: string,
    importedSpecifiers: string[]
  ): Promise<string[]> {
    // Only process potential barrel files
    if (!this.isLikelyBarrelFile(barrelFile)) {
      return []
    }

    const fileInfo = await this.fs.readFile(barrelFile)
    if (!fileInfo.exists) {
      return []
    }

    try {
      // Extract re-exports from the barrel file
      const reExports = this.astParser.extractReExports(fileInfo.content, barrelFile)

      if (reExports.size === 0) {
        return [] // Not a barrel export
      }

      const resolvedFiles: string[] = []

      // Resolve each imported specifier to its actual source
      for (const specifier of importedSpecifiers) {
        // Remove "* as " prefix if present
        const cleanSpecifier = specifier.replace(/^\* as /, '')

        const reExport = reExports.get(cleanSpecifier)
        if (reExport) {
          // Resolve the re-export source relative to the barrel file
          const resolved = this.pathResolver.resolve(reExport.source, barrelFile)
          if (resolved && this.fs.isInProject(resolved)) {
            const relativePath = this.fs.getRelativePath(resolved)
            resolvedFiles.push(relativePath)
          }
        }
      }

      return resolvedFiles
    } catch (error) {
      // If parsing fails, return empty (treat as non-barrel file)
      return []
    }
  }

  /**
   * Check if a file is likely a barrel export file
   */
  private isLikelyBarrelFile(filePath: string): boolean {
    const fileName = filePath.toLowerCase()

    // Common barrel export patterns
    return (
      fileName.endsWith('/index.ts') ||
      fileName.endsWith('/index.tsx') ||
      fileName.endsWith('/index.js') ||
      fileName.endsWith('/index.jsx') ||
      fileName.includes('/pages/index.') ||
      fileName.includes('/components/index.') ||
      fileName.includes('/src/pages.') // e.g., src/pages.ts
    )
  }

  /**
   * Find all files that depend on the given file (transitive dependencies)
   */
  findDependents(
    graph: DependencyGraph,
    changedFile: string,
    maxDepth: number = 10
  ): Set<string> {
    const dependents = new Set<string>()
    const queue: Array<{ file: string; depth: number }> = [
      { file: changedFile, depth: 0 },
    ]
    const visited = new Set<string>()

    while (queue.length > 0) {
      const { file, depth } = queue.shift()!

      if (visited.has(file) || depth > maxDepth) {
        continue
      }

      visited.add(file)

      const node = graph.nodes.get(file)
      if (!node) {
        continue
      }

      // Add this file to dependents (except the original file)
      if (file !== changedFile) {
        dependents.add(file)
      }

      // Add files that depend on this file to the queue
      for (const dependent of node.dependents) {
        if (!visited.has(dependent)) {
          queue.push({ file: dependent, depth: depth + 1 })
        }
      }
    }

    return dependents
  }

  /**
   * Check if file should be excluded
   */
  private shouldExclude(file: string, excludePatterns: string[]): boolean {
    // Always exclude test files and type definition files
    if (
      file.includes('.test.') ||
      file.includes('.spec.') ||
      file.endsWith('.d.ts')
    ) {
      return true
    }

    // Check custom exclude patterns
    for (const pattern of excludePatterns) {
      const regex = this.patternToRegex(pattern)
      if (regex.test(file)) {
        return true
      }
    }

    return false
  }

  /**
   * Convert glob pattern to regex
   */
  private patternToRegex(pattern: string): RegExp {
    const escaped = pattern
      .replace(/\./g, '\\.')
      .replace(/\*/g, '.*')
      .replace(/\?/g, '.')

    return new RegExp(`^${escaped}$`)
  }

  /**
   * Get statistics about the dependency graph
   */
  getGraphStats(graph: DependencyGraph): {
    totalNodes: number
    routeFiles: number
    layoutComponents: number
    pageComponents: number
    averageDependencies: number
    averageDependents: number
  } {
    let routeFiles = 0
    let layoutComponents = 0
    let pageComponents = 0
    let totalDependencies = 0
    let totalDependents = 0

    for (const node of graph.nodes.values()) {
      if (node.isRouteFile) routeFiles++
      if (node.isLayoutComponent) layoutComponents++
      if (node.isPageComponent) pageComponents++
      totalDependencies += node.dependencies.length
      totalDependents += node.dependents.length
    }

    const totalNodes = graph.nodes.size

    return {
      totalNodes,
      routeFiles,
      layoutComponents,
      pageComponents,
      averageDependencies: totalNodes > 0 ? totalDependencies / totalNodes : 0,
      averageDependents: totalNodes > 0 ? totalDependents / totalNodes : 0,
    }
  }
}
